def can_make_k_balanced(n, k, s):
    # Initialize a list to keep track of the balance at each position
    balance = [0] * (n + 1)

    # Calculate the balance at each position
    for i in range(n):
        balance[i + 1] = balance[i] + (1 if s[i] == '1' else -1)

    # Check if the string is already k-balanced
    for i in range(k, n + 1):
        if balance[i] - balance[i - k] == 0:
            return "NO"

    # Try to replace '?' with 0 or 1 to make the string k-balanced
    for i in range(n):
        if s[i] == '?':
            # Check if replacing '?' with 0 makes the substring k-balanced
            if balance[i - k + 1] == balance[i] and balance[i + 1] == balance[i + k]:
                balance[i + 1] = balance[i]
                s = s[:i] + '0' + s[i + 1:]
            # Check if replacing '?' with 1 makes the substring k-balanced
            elif balance[i - k + 1] == balance[i] and balance[i + 1] == balance[i + k]:
                balance[i + 1] = balance[i]
                s = s[:i] + '1' + s[i + 1:]

    # Recalculate the balance after replacements
    for i in range(n):
        balance[i + 1] = balance[i] + (1 if s[i] == '1' else -1)

    # Check if the string is now k-balanced
    for i in range(k, n + 1):
        if balance[i] - balance[i - k] == 0:
            return "NO"

    return "YES"

